package net.zartra.gui;
import java.util.*;
final class ActionRegistry { interface Handler { boolean execute(ActionExecutor.Context context,String value) throws Exception; } static final class Definition { final String id,display;final boolean requiresValue;final Handler handler;Definition(String id,String display,boolean requiresValue,Handler handler){this.id=id;this.display=display;this.requiresValue=requiresValue;this.handler=handler;} } private final Map<String,Definition> entries=new LinkedHashMap<String,Definition>();void register(String id,String display,boolean needs,Handler handler){entries.put(id.toUpperCase(),new Definition(id.toUpperCase(),display,needs,handler));}Definition get(String id){return id==null?null:entries.get(id.toUpperCase());}Collection<Definition> all(){return Collections.unmodifiableCollection(entries.values());}}